// 严格命令与模块选择只转typed语义；未知字段、版本或非原本人决定直接拒绝。
#include "task_shop_order_boundary.hpp"
#include <set>
#include <algorithm>
namespace hanmo::resident {
StableId task_shop_order_command_kind(const TaskShopOrderCommand& c){switch(c.kind){case TaskShopOrderCommand::Kind::accept:return "task_shop_order_accept";case TaskShopOrderCommand::Kind::deliver:return "task_shop_order_deliver";case TaskShopOrderCommand::Kind::cancel:return "task_shop_order_cancel";}return {};}
BoundaryValue encode_task_shop_order_command(const TaskShopOrderCommand& c){return boundary::obj({{c.kind==TaskShopOrderCommand::Kind::accept?"order_id":"task_id",BoundaryValue{c.id}}});}
Outcome<TaskShopOrderCommand> decode_task_shop_order_command(const StableId& kind,const BoundaryValue& value){try{using namespace boundary;TaskShopOrderCommand result;if(kind=="task_shop_order_accept")result.kind=TaskShopOrderCommand::Kind::accept;else if(kind=="task_shop_order_deliver")result.kind=TaskShopOrderCommand::Kind::deliver;else if(kind=="task_shop_order_cancel")result.kind=TaskShopOrderCommand::Kind::cancel;else unsupported("UnsupportedTaskShopOrderCommand",kind);std::set<StableId> names;for(const auto& row:object(value,kind))if(!names.insert(row.first).second)fail("DuplicateTaskShopOrderCommandField",row.first);const char* key=result.kind==TaskShopOrderCommand::Kind::accept?"order_id":"task_id";fields(value,{key},{},kind);result.id=get_string(value,key,kind);if(result.id.empty())fail("InvalidTaskShopOrderId",key);return {true,std::move(result),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<bool> decode_task_shop_order_profile(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){try{using namespace boundary;const auto* selected=scenario.find("task_shop_order_profile");if(!selected)return {true,false,{}};if(string(*selected,"task_shop_order_profile")!="private_shop_orders_v1")unsupported("UnsupportedTaskShopOrderProfile","task_shop_order_profile");if(std::find(capabilities.begin(),capabilities.end(),"task_shop_orders_v1")==capabilities.end())unsupported("TaskShopOrderCapabilityRequired","task_shop_order_profile");const auto* dynamic=scenario.find("dynamic_world");if(!dynamic||get_string(*dynamic,"profile","dynamic_world")!="local_society_v1"||!dynamic->find("private_shops"))unsupported("PrivateShopProfileRequired","task_shop_order_profile");return {true,true,{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status validate_task_shop_order_layout(const std::vector<std::pair<StableId,StableId>>& modules,bool enabled,bool shop,bool policies,const TaskShopOrderState* state){Integer count=0;for(const auto& m:modules)if(m.first==task_shop_order_module){++count;if(m.second!="1")return common_failure("UnsupportedTaskShopOrderVersion");}if(count!=(enabled?1:0)||enabled!=bool(state)||(enabled&&(!shop||!policies||state->version!=1))||(!enabled&&policies))return common_failure("TaskShopOrderProfileMismatch");return common_success();}
Status validate_task_shop_order_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,bool enabled,bool shop,bool policies,const TaskShopOrderState* state){auto valid=validate_task_shop_order_layout(modules,enabled,shop,policies,state);if(!valid.ok||enabled)return valid;for(const auto& row:common.state().facts.rows())if(row.second.domain==task_shop_order_domain||row.second.kind==task_shop_order_acceptance_kind||row.second.kind==task_shop_order_settled_kind||row.second.kind==task_shop_order_interrupted_kind)return common_failure("TaskShopOrderProfileRequired",row.first);for(const auto& row:common.state().actions.rows())if(row.second.kind=="task_shop_order_deliver")return common_failure("TaskShopOrderProfileRequired",row.first);return common_success();}
Status preview_task_shop_order_cancellation(const CommonStore& common,const TaskState& tasks,const TaskShopOrderState& state,const PrivateShopOrderRead& shop,const StableId& actor,const StableId& id){const auto* task=tasks.tasks.find(id);if(!task||task->assignee!=actor)return common_failure("TaskNotKnown");auto valid=validate_task_shop_order_execution(common,tasks,state,shop);if(!valid.ok)return valid;const auto* person=common.actor(actor);if(!state.by_task.count(id)||task->status!="active"||!person||!person->alive||!person->available||!person->action_id.empty())return common_failure("TaskShopOrderCancellationUnavailable");for(const auto& row:state.actions.rows())if(row.second.task_id==id)return common_failure("TaskShopOrderActionStillActive");return common_success();}
}
